export function ContainerQuery({
  width = {{width}},
  cardTitle = "{{cardTitle}}",
  showRuler = {{showRuler}},
  accent = "{{accent}}",
}) {
  return (
    <div style={{ width: "100%", maxWidth: 660 }}>
      {showRuler && <div style={{ width, fontSize: 11, color: "#241430aa", borderBottom: "1px dashed #24143044", paddingBottom: 4, marginBottom: 8, textAlign: "right" }}>{width}px</div>}
      <div style={{ width, maxWidth: "100%", containerType: "inline-size", background: "#FAF7F2", border: "1px solid #24143022", borderRadius: 12, padding: 14, boxSizing: "border-box" }}>
        <div className="card" style={{ display: "flex", flexDirection: "column", gap: 10, fontFamily: "system-ui, sans-serif", fontSize: 13, color: "#241430" }}>
          <span className="thumb" style={{ width: "100%", height: 60, borderRadius: 8, background: accent }} />
          <div>
            <strong>{cardTitle}</strong>
            <p style={{ margin: "4px 0 0", color: "#241430aa", fontSize: 12 }}>Layout is driven by the CARD's own width, not the viewport.</p>
          </div>
        </div>
      </div>
      <style>{`
        @container (min-width: 340px) {
          .card { flex-direction: row; align-items: center; }
          .thumb { width: 72px; height: 72px; flex: none; }
        }
      `}</style>
    </div>
  );
}
